v3"/></svg><input id="kata-sandi" name="kata_sandi" type="password" placeholder="••••••••" required autocomplete="current-password" class="login-field__input"><button id="tombol-lihat-sandi" type="button" aria-label="Tampilkan kata sandi" class="login-field__toggle"><svg class="eye-open" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/></svg><svg class="eye-closed hidden" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="m3 3 18 18M10.6 6.2A10.8 10.8 0 0 1 12 6c6 0 9.5 6 9.5 6a17 17 0 0 1-2.4 3.2M6.2 6.3C3.9 8 2.5 12 2.5 12s3.5 6 9.5 6c1.4 0 2.7-.3 3.8-.8"/></svg></button></div>@error('kata_sandi')<span class="mt-2 block text-sm text-red-600">{{ $message }}</span>@enderror</label><label class="flex items-center gap-2 text-sm text-slate-600"><input name="ingat_saya" type="checkbox" value="1" class="rounded border-slate-300 text-emerald-600 focus:ring-emerald-500"> Ingat saya</label><button type="submit" class="login-submit">Masuk</button></form></section></div></main><script>const passwordInput=document.getElementById('kata-sandi');const togglePassword=document.getElementById('tombol-lihat-sandi');if(passwordInput&&togglePassword){togglePassword.addEventListener('click',()=>{const visible=passwordInput.type==='text';passwordInput.type=visible?'password':'text';togglePassword.setAttribute('aria-label',visible?'Tampilkan kata sandi':'Sembunyikan kata sandi');togglePassword.classList.add('is-tapped');setTimeout(()=>togglePassword.classList.remove('is-tapped'),180);togglePassword.querySelector('.eye-open').classList.toggle('hidden',!visible);togglePassword.querySelector('.eye-closed').classList.toggle('hidden',visible);});}</script></body>
